// Ported from the Node app's Sequelize model StaffAttendance (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class StaffAttendanceConfiguration : IEntityTypeConfiguration<StaffAttendance>
{
    public void Configure(EntityTypeBuilder<StaffAttendance> builder)
    {
        builder.ToTable("staff_attendance", t =>
        {
            t.HasCheckConstraint("CK_staff_attendance_status", "[status] IN (N'present', N'absent', N'late', N'leave')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StaffId).HasColumnName("staff_id");
        builder.Property(e => e.Date).HasColumnName("date").HasColumnType("date");
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired();
        builder.HasIndex(e => new { e.StaffId, e.Date }).IsUnique().HasDatabaseName("uq_staff_att");
        builder.HasOne(e => e.Staff).WithMany(p => p.StaffAttendances).HasForeignKey(e => e.StaffId).OnDelete(DeleteBehavior.NoAction);
    }
}
